import csv, json, os, sys
path = os.path.expanduser('~/Desktop/seguro_wf_eval/h3/ledger_quickbooks.csv')
# Assuming CSV has columns: date, amount maybe. We'll parse date column and sum amounts per month.
# Try to infer column names.
with open(path, newline='', encoding='utf-8') as f:
    reader = csv.DictReader(f)
    rows = list(reader)
    # Find date column (contains 'date' case-insensitive)
    date_col = None
    amount_col = None
    for col in reader.fieldnames:
        lc = col.lower()
        if 'date' in lc:
            date_col = col
        if 'amount' in lc or 'value' in lc or 'amt' in lc:
            amount_col = col
    if not date_col or not amount_col:
        # fallback: assume first column is date, second is amount
        date_col = reader.fieldnames[0]
        amount_col = reader.fieldnames[1]
    # Compute totals
    totals = {'July':0.0, 'August':0.0, 'September':0.0}
    for r in rows:
        date_str = r[date_col]
        # parse date, assume format YYYY-MM-DD or MM/DD/YYYY etc.
        import datetime
        try:
            dt = datetime.datetime.strptime(date_str, '%Y-%m-%d')
        except ValueError:
            try:
                dt = datetime.datetime.strptime(date_str, '%m/%d/%Y')
            except ValueError:
                # try other common format
                try:
                    dt = datetime.datetime.strptime(date_str, '%d-%m-%Y')
                except Exception:
                    continue
        if dt.year == 2026:
            month_name = dt.strftime('%B')
            if month_name in totals:
                try:
                    amt = float(r[amount_col])
                except Exception:
                    # remove commas, currency symbols
                    amt = float(r[amount_col].replace('$','').replace(',',''))
                totals[month_name] += amt
    # Build table rows
    table = [['Month','Total']]
    for m in ['July','August','September']:
        table.append([m, round(totals[m],2)])
    print(json.dumps(table))

import csv, json, os, sys
file_path = os.path.expanduser('~/Desktop/seguro_wf_eval/h3/ledger_salesforce.csv')
# Expect columns: date, amount maybe. We'll parse date column and sum amounts per month.
monthly = {'2026-07':0.0,'2026-08':0.0,'2026-09':0.0}
with open(file_path, newline='', encoding='utf-8') as f:
    reader = csv.DictReader(f)
    # Determine date column name (contains 'date') and amount column (contains 'amount' or 'value')
    date_col = None
    amount_col = None
    for col in reader.fieldnames:
        lc = col.lower()
        if 'date' in lc:
            date_col = col
        if 'amount' in lc or 'value' in lc or 'amt' in lc:
            amount_col = col
    if not date_col or not amount_col:
        raise ValueError('Could not find date or amount column')
    for row in reader:
        date = row[date_col]
        # parse year-month
        # assume format YYYY-MM-DD or similar
        try:
            ym = '-'.join(date.split('-')[:2])
        except Exception:
            continue
        if ym in monthly:
            try:
                amt = float(row[amount_col].replace(',',''))
            except Exception:
                amt = 0.0
            monthly[ym] += amt
# Build table rows: header then rows for each month in order
header = ['Month','Total']
rows = [header]
for month in ['2026-07','2026-08','2026-09']:
    rows.append([month, round(monthly[month],2)])
print(json.dumps(rows))

