import pytest
from textstats import word_frequencies

def test_word_frequencies_empty_string():
    assert word_frequencies("") == {}

def test_word_frequencies_single_word():
    assert word_frequencies("hello") == {"hello": 1}

def test_word_frequencies_multiple_words():
    assert word_frequencies("hello world hello") == {"hello": 2, "world": 1}

